"""Integration tests with independent exFAT filesystem tools (mkfs.exfat)."""

import shutil
import subprocess
from pathlib import Path

import pytest

from recoverx.domain.enums import FileSystemType
from recoverx.filesystems.exfat.parser import ExFatFileSystem
from recoverx.infrastructure.storage.image import DiskImageReader

HAS_MKFS_EXFAT = shutil.which("mkfs.exfat") is not None


@pytest.mark.skipif(not HAS_MKFS_EXFAT, reason="mkfs.exfat is not installed on this host")
def test_mkfs_exfat_generated_image(tmp_path: Path) -> None:
    """Verify that images generated by official mkfs.exfat are detected and parsed correctly."""
    img_path = tmp_path / "mkfs_exfat.img"
    # Create 32 MB empty file
    with open(img_path, "wb") as f:
        f.seek(32 * 1024 * 1024 - 1)
        f.write(b"\x00")

    # Format using mkfs.exfat -n LINUX_EXFAT
    res = subprocess.run(
        ["mkfs.exfat", "-n", "LINUX_EXFAT", str(img_path)],
        capture_output=True,
        text=True,
        check=False,
    )
    assert res.returncode == 0, f"mkfs.exfat failed: {res.stderr}"

    fs = ExFatFileSystem()
    with DiskImageReader(img_path) as reader:
        assert fs.detect(reader)
        info = fs.get_fs_info(reader)
        assert info is not None
        assert info.fs_type == FileSystemType.EXFAT
        assert "LINUX_EXFAT" in info.volume_label
        assert info.cluster_size_bytes in (512, 1024, 2048, 4096, 8192, 16384, 32768)
